export type EventStatus = 'pending' | 'processing' | 'delivered' | 'failed';

export type SubscriptionStatus = 'active' | 'degraded';

export interface Subscription {
  id: string;
  customer_id: string;
  endpoint_url: string;
  secret: string;
  consecutive_failures: number;
  status: SubscriptionStatus;
  created_at: number; // Unix ms
}

export interface WebhookEvent {
  id: string;
  customer_id: string;
  subscription_id: string;
  event_type: string;
  payload: Record<string, any>;
  sequence_number: number;
  status: EventStatus;
  attempt_count: number;
  max_attempts: number;
  next_attempt_at: number; // Unix ms
  created_at: number;      // Unix ms
  delivered_at: number | null;
  last_error: string | null;
}

export interface DeliveryAttempt {
  id: string;
  event_id: string;
  attempt_number: number;
  started_at: number;
  finished_at: number;
  status_code: number | null;
  response_body: string | null;
  error_message: string | null;
  duration_ms: number;
}

export interface CreateSubscriptionInput {
  customerId: string;
  endpointUrl: string;
  secret?: string;
}

export interface IngestEventInput {
  customerId: string;
  eventType?: string;
  payload: Record<string, any>;
}

export interface RetryPolicy {
  maxAttempts: number;
  initialDelayMs: number;
  backoffFactor: number;
  maxDelayMs: number;
  jitterFactor: number; // 0.0 - 1.0
  requestTimeoutMs: number;
}

import crypto from 'node:crypto';

/**
 * Computes an HMAC SHA-256 signature for a webhook payload.
 * Format: sha256=<hex_digest>
 */
export function signPayload(payloadString: string, secret: string): string {
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(payloadString, 'utf8');
  return `sha256=${hmac.digest('hex')}`;
}

/**
 * Timing-safe signature verification helper.
 */
export function verifySignature(
  payloadString: string,
  secret: string,
  providedSignature: string
): boolean {
  const expected = signPayload(payloadString, secret);
  if (expected.length !== providedSignature.length) {
    return false;
  }
  return crypto.timingSafeEqual(
    Buffer.from(expected, 'utf8'),
    Buffer.from(providedSignature, 'utf8')
  );
}

/**
 * Generates a random secure secret if none provided.
 */
export function generateSecret(): string {
  return 'whsec_' + crypto.randomBytes(24).toString('hex');
}

import Database from 'better-sqlite3';
import {
  Subscription,
  WebhookEvent,
  DeliveryAttempt,
  EventStatus,
  SubscriptionStatus,
} from './types.js';
import crypto from 'node:crypto';

export class WebhookStore {
  private db: Database.Database;

  constructor(dbPath: string = 'webhooks.db') {
    this.db = new Database(dbPath);
    this.db.pragma('journal_mode = WAL');
    this.db.pragma('foreign_keys = ON');
    this.initSchema();
  }

  private initSchema() {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS subscriptions (
        id TEXT PRIMARY KEY,
        customer_id TEXT NOT NULL UNIQUE,
        endpoint_url TEXT NOT NULL,
        secret TEXT NOT NULL,
        consecutive_failures INTEGER NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'active',
        created_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS customer_sequences (
        customer_id TEXT PRIMARY KEY,
        last_sequence INTEGER NOT NULL DEFAULT 0
      );

      CREATE TABLE IF NOT EXISTS events (
        id TEXT PRIMARY KEY,
        customer_id TEXT NOT NULL,
        subscription_id TEXT NOT NULL,
        event_type TEXT NOT NULL,
        payload TEXT NOT NULL,
        sequence_number INTEGER NOT NULL,
        status TEXT NOT NULL,
        attempt_count INTEGER NOT NULL DEFAULT 0,
        max_attempts INTEGER NOT NULL DEFAULT 5,
        next_attempt_at INTEGER NOT NULL,
        created_at INTEGER NOT NULL,
        delivered_at INTEGER,
        last_error TEXT,
        FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE CASCADE
      );

      CREATE INDEX IF NOT EXISTS idx_events_poll 
        ON events(status, next_attempt_at);

      CREATE INDEX IF NOT EXISTS idx_events_customer 
        ON events(customer_id, created_at DESC);

      CREATE TABLE IF NOT EXISTS delivery_attempts (
        id TEXT PRIMARY KEY,
        event_id TEXT NOT NULL,
        attempt_number INTEGER NOT NULL,
        started_at INTEGER NOT NULL,
        finished_at INTEGER NOT NULL,
        status_code INTEGER,
        response_body TEXT,
        error_message TEXT,
        duration_ms INTEGER NOT NULL,
        FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE
      );

      CREATE INDEX IF NOT EXISTS idx_delivery_attempts_event 
        ON delivery_attempts(event_id, started_at ASC);
    `);
  }

  // --- Subscriptions ---

  upsertSubscription(
    customerId: string,
    endpointUrl: string,
    secret: string
  ): Subscription {
    const existing = this.getSubscriptionByCustomerId(customerId);
    const now = Date.now();

    if (existing) {
      const stmt = this.db.prepare(`
        UPDATE subscriptions 
        SET endpoint_url = ?, secret = ?, consecutive_failures = 0, status = 'active'
        WHERE id = ?
      `);
      stmt.run(endpointUrl, secret, existing.id);
      return this.getSubscriptionById(existing.id)!;
    }

    const id = 'sub_' + crypto.randomUUID().slice(0, 12);
    const stmt = this.db.prepare(`
      INSERT INTO subscriptions (id, customer_id, endpoint_url, secret, consecutive_failures, status, created_at)
      VALUES (?, ?, ?, ?, 0, 'active', ?)
    `);
    stmt.run(id, customerId, endpointUrl, secret, now);
    return this.getSubscriptionById(id)!;
  }

  getSubscriptionById(id: string): Subscription | null {
    const row = this.db.prepare('SELECT * FROM subscriptions WHERE id = ?').get(id);
    return row ? (row as Subscription) : null;
  }

  getSubscriptionByCustomerId(customerId: string): Subscription | null {
    const row = this.db
      .prepare('SELECT * FROM subscriptions WHERE customer_id = ?')
      .get(customerId);
    return row ? (row as Subscription) : null;
  }

  listSubscriptions(): Subscription[] {
    return this.db.prepare('SELECT * FROM subscriptions ORDER BY created_at DESC').all() as Subscription[];
  }

  updateSubscriptionDegradedStatus(
    subscriptionId: string,
    consecutiveFailures: number,
    status: SubscriptionStatus
  ): void {
    this.db
      .prepare(
        'UPDATE subscriptions SET consecutive_failures = ?, status = ? WHERE id = ?'
      )
      .run(consecutiveFailures, status, subscriptionId);
  }

  // --- Events ---

  private nextSequence(customerId: string): number {
    const getSeq = this.db.prepare(
      'SELECT last_sequence FROM customer_sequences WHERE customer_id = ?'
    );
    const row = getSeq.get(customerId) as { last_sequence: number } | undefined;

    if (!row) {
      this.db
        .prepare('INSERT INTO customer_sequences (customer_id, last_sequence) VALUES (?, 1)')
        .run(customerId);
      return 1;
    }

    const next = row.last_sequence + 1;
    this.db
      .prepare('UPDATE customer_sequences SET last_sequence = ? WHERE customer_id = ?')
      .run(next, customerId);
    return next;
  }

  createEvent(
    customerId: string,
    subscriptionId: string,
    eventType: string,
    payload: Record<string, any>,
    maxAttempts: number = 5
  ): WebhookEvent {
    const transaction = this.db.transaction(() => {
      const seq = this.nextSequence(customerId);
      const id = 'evt_' + crypto.randomUUID().replace(/-/g, '').slice(0, 16);
      const now = Date.now();

      const stmt = this.db.prepare(`
        INSERT INTO events (
          id, customer_id, subscription_id, event_type, payload,
          sequence_number, status, attempt_count, max_attempts,
          next_attempt_at, created_at, delivered_at, last_error
        ) VALUES (?, ?, ?, ?, ?, ?, 'pending', 0, ?, ?, ?, NULL, NULL)
      `);

      stmt.run(
        id,
        customerId,
        subscriptionId,
        eventType,
        JSON.stringify(payload),
        seq,
        maxAttempts,
        now, // immediately eligible
        now
      );

      return this.getEventById(id)!;
    });

    return transaction();
  }

  getEventById(id: string): (WebhookEvent & { attempts: DeliveryAttempt[] }) | null {
    const row = this.db.prepare('SELECT * FROM events WHERE id = ?').get(id) as any;
    if (!row) return null;

    const attempts = this.db
      .prepare('SELECT * FROM delivery_attempts WHERE event_id = ? ORDER BY attempt_number ASC')
      .all(id) as DeliveryAttempt[];

    return {
      ...row,
      payload: JSON.parse(row.payload),
      attempts,
    };
  }

  listEvents(filters?: {
    customerId?: string;
    status?: EventStatus;
    limit?: number;
    offset?: number;
  }): { events: WebhookEvent[]; total: number } {
    let whereClauses: string[] = [];
    let params: any[] = [];

    if (filters?.customerId) {
      whereClauses.push('customer_id = ?');
      params.push(filters.customerId);
    }

    if (filters?.status) {
      whereClauses.push('status = ?');
      params.push(filters.status);
    }

    const whereStr = whereClauses.length > 0 ? `WHERE ${whereClauses.join(' AND ')}` : '';
    const limit = filters?.limit ?? 50;
    const offset = filters?.offset ?? 0;

    const countRow = this.db
      .prepare(`SELECT COUNT(*) as total FROM events ${whereStr}`)
      .get(...params) as { total: number };

    const rows = this.db
      .prepare(`SELECT * FROM events ${whereStr} ORDER BY created_at DESC LIMIT ? OFFSET ?`)
      .all(...params, limit, offset) as any[];

    const events = rows.map((r) => ({
      ...r,
      payload: JSON.parse(r.payload),
    }));

    return { events, total: countRow.total };
  }

  /**
   * Fetch due pending events for processing.
   * Excludes events for customers who currently have active in-flight requests exceeding limit,
   * to guarantee fair sharing across customers and avoid head-of-line blocking.
   */
  fetchDueEvents(
    maxBatch: number,
    excludedCustomerIds: string[] = []
  ): WebhookEvent[] {
    const now = Date.now();
    let query = `
      SELECT * FROM events 
      WHERE status = 'pending' AND next_attempt_at <= ?
    `;
    const params: any[] = [now];

    if (excludedCustomerIds.length > 0) {
      const placeholders = excludedCustomerIds.map(() => '?').join(',');
      query += ` AND customer_id NOT IN (${placeholders})`;
      params.push(...excludedCustomerIds);
    }

    query += ` ORDER BY next_attempt_at ASC, sequence_number ASC LIMIT ?`;
    params.push(maxBatch);

    const rows = this.db.prepare(query).all(...params) as any[];
    return rows.map((r) => ({
      ...r,
      payload: JSON.parse(r.payload),
    }));
  }

  /**
   * Mark event as currently processing (in-flight)
   */
  claimEventForProcessing(eventId: string): boolean {
    const res = this.db
      .prepare(`UPDATE events SET status = 'processing' WHERE id = ? AND status = 'pending'`)
      .run(eventId);
    return res.changes > 0;
  }

  /**
   * Records a completed delivery attempt and updates the event's lifecycle status.
   */
  recordAttempt(
    eventId: string,
    attempt: {
      attemptNumber: number;
      startedAt: number;
      finishedAt: number;
      statusCode: number | null;
      responseBody: string | null;
      errorMessage: string | null;
      durationMs: number;
    },
    nextStatus: EventStatus,
    nextAttemptAt: number | null,
    lastError: string | null
  ): void {
    const transaction = this.db.transaction(() => {
      const attemptId = 'att_' + crypto.randomUUID().slice(0, 16);
      this.db
        .prepare(`
          INSERT INTO delivery_attempts (
            id, event_id, attempt_number, started_at, finished_at,
            status_code, response_body, error_message, duration_ms
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        `)
        .run(
          attemptId,
          eventId,
          attempt.attemptNumber,
          attempt.startedAt,
          attempt.finishedAt,
          attempt.statusCode,
          attempt.responseBody,
          attempt.errorMessage,
          attempt.durationMs
        );

      const deliveredAt = nextStatus === 'delivered' ? attempt.finishedAt : null;

      this.db
        .prepare(`
          UPDATE events 
          SET status = ?,
              attempt_count = ?,
              next_attempt_at = COALESCE(?, next_attempt_at),
              delivered_at = COALESCE(?, delivered_at),
              last_error = ?
          WHERE id = ?
        `)
        .run(
          nextStatus,
          attempt.attemptNumber,
          nextAttemptAt,
          deliveredAt,
          lastError,
          eventId
        );
    });

    transaction();
  }

  /**
   * Replay / manually retry a failed or delivered event.
   */
  retryEvent(eventId: string): WebhookEvent | null {
    const now = Date.now();
    const res = this.db
      .prepare(`
        UPDATE events 
        SET status = 'pending',
            next_attempt_at = ?,
            attempt_count = 0,
            last_error = NULL
        WHERE id = ?
      `)
      .run(now, eventId);

    if (res.changes === 0) return null;
    return this.getEventById(eventId);
  }

  getStats(): {
    totalEvents: number;
    pending: number;
    processing: number;
    delivered: number;
    failed: number;
    subscriptions: number;
  } {
    const counts = this.db
      .prepare(`
        SELECT 
          COUNT(*) as total,
          SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) as pending,
          SUM(CASE WHEN status = 'processing' THEN 1 ELSE 0 END) as processing,
          SUM(CASE WHEN status = 'delivered' THEN 1 ELSE 0 END) as delivered,
          SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) as failed
        FROM events
      `)
      .get() as any;

    const subCount = this.db
      .prepare('SELECT COUNT(*) as count FROM subscriptions')
      .get() as any;

    return {
      totalEvents: counts.total || 0,
      pending: counts.pending || 0,
      processing: counts.processing || 0,
      delivered: counts.delivered || 0,
      failed: counts.failed || 0,
      subscriptions: subCount.count || 0,
    };
  }

  close() {
    this.db.close();
  }
}

import { WebhookStore } from './db.js';
import {
  WebhookEvent,
  Subscription,
  RetryPolicy,
  EventStatus,
} from './types.js';
import { signPayload } from './crypto.js';

export interface DispatcherOptions {
  store: WebhookStore;
  policy?: Partial<RetryPolicy>;
  pollIntervalMs?: number;
  maxGlobalConcurrency?: number;
  maxConcurrentPerCustomer?: number;
}

export class WebhookDispatcher {
  private store: WebhookStore;
  private policy: RetryPolicy;
  private pollIntervalMs: number;
  private maxGlobalConcurrency: number;
  private maxConcurrentPerCustomer: number;

  private isRunning: boolean = false;
  private pollTimer: NodeJS.Timeout | null = null;

  // Track currently active in-flight deliveries
  private activeGlobalCount: number = 0;
  private activePerCustomer: Map<string, number> = new Map();

  constructor(options: DispatcherOptions) {
    this.store = options.store;
    this.pollIntervalMs = options.pollIntervalMs ?? 500;
    this.maxGlobalConcurrency = options.maxGlobalConcurrency ?? 10;
    this.maxConcurrentPerCustomer = options.maxConcurrentPerCustomer ?? 2;

    this.policy = {
      maxAttempts: 5,
      initialDelayMs: 2000,   // 2s
      backoffFactor: 2,       // 2x exponential
      maxDelayMs: 60000,      // 60s max backoff
      jitterFactor: 0.2,      // +/- 20% jitter
      requestTimeoutMs: 5000, // 5s HTTP timeout
      ...options.policy,
    };
  }

  start() {
    if (this.isRunning) return;
    this.isRunning = true;
    this.scheduleNextPoll(0);
  }

  stop() {
    this.isRunning = false;
    if (this.pollTimer) {
      clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }
  }

  private scheduleNextPoll(delayMs: number = this.pollIntervalMs) {
    if (!this.isRunning) return;
    this.pollTimer = setTimeout(() => {
      this.pollAndDispatch().catch((err) => {
        console.error('[Dispatcher] Error in polling loop:', err);
      }).finally(() => {
        if (this.isRunning) {
          this.scheduleNextPoll();
        }
      });
    }, delayMs);
  }

  /**
   * Main dispatch loop: fetches ready events considering per-customer fair limits.
   */
  async pollAndDispatch() {
    const availableSlots = this.maxGlobalConcurrency - this.activeGlobalCount;
    if (availableSlots <= 0) {
      return; // All global workers busy
    }

    // Identify customers who have reached their concurrency limit
    const saturatedCustomers: string[] = [];
    for (const [custId, count] of this.activePerCustomer.entries()) {
      if (count >= this.maxConcurrentPerCustomer) {
        saturatedCustomers.push(custId);
      }
    }

    // Fetch batch of ready events excluding saturated customers
    const events = this.store.fetchDueEvents(availableSlots, saturatedCustomers);
    if (events.length === 0) {
      return;
    }

    for (const event of events) {
      // Re-verify slot availability
      const currentCustCount = this.activePerCustomer.get(event.customer_id) || 0;
      if (
        this.activeGlobalCount >= this.maxGlobalConcurrency ||
        currentCustCount >= this.maxConcurrentPerCustomer
      ) {
        continue;
      }

      // Atomically mark event as processing in database
      const claimed = this.store.claimEventForProcessing(event.id);
      if (!claimed) {
        continue;
      }

      // Increment concurrency counters
      this.activeGlobalCount++;
      this.activePerCustomer.set(event.customer_id, currentCustCount + 1);

      // Execute delivery asynchronously in background
      this.deliverEvent(event).finally(() => {
        this.activeGlobalCount--;
        const updated = (this.activePerCustomer.get(event.customer_id) || 1) - 1;
        if (updated <= 0) {
          this.activePerCustomer.delete(event.customer_id);
        } else {
          this.activePerCustomer.set(event.customer_id, updated);
        }
      });
    }
  }

  /**
   * Calculates exponential backoff with jitter.
   */
  calculateNextAttemptDelay(attemptNumber: number): number {
    const baseDelay =
      this.policy.initialDelayMs *
      Math.pow(this.policy.backoffFactor, attemptNumber - 1);
    const cappedDelay = Math.min(baseDelay, this.policy.maxDelayMs);

    // Apply full or equal jitter: delay * (1 - jitter ... 1 + jitter)
    const jitterRange = cappedDelay * this.policy.jitterFactor;
    const randomJitter = (Math.random() * 2 - 1) * jitterRange;
    return Math.max(100, Math.floor(cappedDelay + randomJitter));
  }

  /**
   * Executes HTTP POST delivery of a single event to the customer's registered endpoint.
   */
  private async deliverEvent(event: WebhookEvent): Promise<void> {
    const subscription = this.store.getSubscriptionById(event.subscription_id);
    if (!subscription) {
      this.store.recordAttempt(
        event.id,
        {
          attemptNumber: event.attempt_count + 1,
          startedAt: Date.now(),
          finishedAt: Date.now(),
          statusCode: null,
          responseBody: null,
          errorMessage: `Subscription ${event.subscription_id} not found`,
          durationMs: 0,
        },
        'failed',
        null,
        'Subscription not found'
      );
      return;
    }

    const attemptNumber = event.attempt_count + 1;
    const payloadString = JSON.stringify(event.payload);
    const signature = signPayload(payloadString, subscription.secret);
    const timestamp = Date.now();

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'User-Agent': 'WebhookDeliveryService/1.0',
      'X-Webhook-ID': event.id,
      'X-Webhook-Event': event.event_type,
      'X-Webhook-Timestamp': timestamp.toString(),
      'X-Webhook-Attempt': attemptNumber.toString(),
      'X-Webhook-Sequence': event.sequence_number.toString(),
      'X-Webhook-Signature': signature,
    };

    const controller = new AbortController();
    const timeout = setTimeout(() => {
      controller.abort();
    }, this.policy.requestTimeoutMs);

    const startedAt = Date.now();
    let statusCode: number | null = null;
    let responseBody: string | null = null;
    let errorMessage: string | null = null;
    let isSuccess = false;

    try {
      const response = await fetch(subscription.endpoint_url, {
        method: 'POST',
        headers,
        body: payloadString,
        signal: controller.signal,
      });

      statusCode = response.status;
      try {
        const text = await response.text();
        responseBody = text.slice(0, 1024); // Cap preview to 1KB
      } catch {
        responseBody = '';
      }

      // We consider standard 2xx as successful delivery
      if (response.ok) {
        isSuccess = true;
      } else {
        errorMessage = `HTTP error status ${response.status}: ${response.statusText}`;
      }
    } catch (err: any) {
      if (err.name === 'AbortError') {
        errorMessage = `Request timed out after ${this.policy.requestTimeoutMs}ms`;
      } else {
        errorMessage = `Network or connection failure: ${err.message}`;
      }
    } finally {
      clearTimeout(timeout);
    }

    const finishedAt = Date.now();
    const durationMs = finishedAt - startedAt;

    if (isSuccess) {
      // Successful delivery
      this.store.recordAttempt(
        event.id,
        {
          attemptNumber,
          startedAt,
          finishedAt,
          statusCode,
          responseBody,
          errorMessage: null,
          durationMs,
        },
        'delivered',
        null,
        null
      );

      // Reset customer degraded status if any
      if (subscription.consecutive_failures > 0) {
        this.store.updateSubscriptionDegradedStatus(
          subscription.id,
          0,
          'active'
        );
      }
    } else {
      // Delivery failed
      const consecutiveFailures = subscription.consecutive_failures + 1;
      const isDegraded = consecutiveFailures >= 3;

      this.store.updateSubscriptionDegradedStatus(
        subscription.id,
        consecutiveFailures,
        isDegraded ? 'degraded' : 'active'
      );

      if (attemptNumber >= event.max_attempts) {
        // Reached terminal failure state
        this.store.recordAttempt(
          event.id,
          {
            attemptNumber,
            startedAt,
            finishedAt,
            statusCode,
            responseBody,
            errorMessage,
            durationMs,
          },
          'failed',
          null,
          `Max attempts (${event.max_attempts}) exceeded. Last error: ${errorMessage}`
        );
      } else {
        // Schedule next retry with exponential backoff & jitter
        let delayMs = this.calculateNextAttemptDelay(attemptNumber);

        // If customer is severely degraded (long outage), add outage protection multiplier
        if (isDegraded) {
          delayMs = Math.min(delayMs * 1.5, this.policy.maxDelayMs);
        }

        const nextAttemptAt = Date.now() + delayMs;

        this.store.recordAttempt(
          event.id,
          {
            attemptNumber,
            startedAt,
            finishedAt,
            statusCode,
            responseBody,
            errorMessage,
            durationMs,
          },
          'pending',
          nextAttemptAt,
          errorMessage
        );
      }
    }
  }

  getMetrics() {
    return {
      activeGlobalCount: this.activeGlobalCount,
      maxGlobalConcurrency: this.maxGlobalConcurrency,
      activePerCustomer: Object.fromEntries(this.activePerCustomer.entries()),
      maxConcurrentPerCustomer: this.maxConcurrentPerCustomer,
      policy: this.policy,
    };
  }
}

import express, { Request, Response } from 'express';
import { WebhookStore } from './db.js';
import { WebhookDispatcher } from './dispatcher.js';
import { generateSecret } from './crypto.js';
import { EventStatus } from './types.js';

export function createApiRouter(store: WebhookStore, dispatcher: WebhookDispatcher) {
  const router = express.Router();

  // --- Subscriptions ---

  /**
   * Register or update a customer endpoint
   * POST /subscriptions
   */
  router.post('/subscriptions', (req: Request, res: Response) => {
    const { customerId, endpointUrl, secret } = req.body;

    if (!customerId || typeof customerId !== 'string') {
      res.status(400).json({ error: 'Missing or invalid customerId' });
      return;
    }
    if (!endpointUrl || typeof endpointUrl !== 'string') {
      res.status(400).json({ error: 'Missing or invalid endpointUrl' });
      return;
    }

    try {
      new URL(endpointUrl);
    } catch {
      res.status(400).json({ error: 'Invalid endpointUrl format. Must be a valid URL' });
      return;
    }

    const subSecret = secret && typeof secret === 'string' ? secret : generateSecret();
    const subscription = store.upsertSubscription(customerId, endpointUrl, subSecret);

    res.status(201).json({
      message: 'Subscription registered successfully',
      subscription,
    });
  });

  /**
   * List all subscriptions
   * GET /subscriptions
   */
  router.get('/subscriptions', (_req: Request, res: Response) => {
    const subscriptions = store.listSubscriptions();
    res.json({ subscriptions });
  });

  /**
   * Get subscription by customer ID
   * GET /subscriptions/:customerId
   */
  router.get('/subscriptions/:customerId', (req: Request, res: Response) => {
    const subscription = store.getSubscriptionByCustomerId(req.params.customerId);
    if (!subscription) {
      res.status(404).json({ error: 'Subscription not found for customer' });
      return;
    }
    res.json({ subscription });
  });

  // --- Events ---

  /**
   * Ingest an event from internal producers
   * POST /events
   */
  router.post('/events', (req: Request, res: Response) => {
    const { customerId, eventType, payload, maxAttempts } = req.body;

    if (!customerId || typeof customerId !== 'string') {
      res.status(400).json({ error: 'Missing or invalid customerId' });
      return;
    }

    if (!payload || typeof payload !== 'object') {
      res.status(400).json({ error: 'Missing or invalid payload (must be JSON object)' });
      return;
    }

    const subscription = store.getSubscriptionByCustomerId(customerId);
    if (!subscription) {
      res.status(404).json({
        error: `Customer '${customerId}' does not have a registered webhook endpoint. Please register via POST /subscriptions first.`,
      });
      return;
    }

    const type = eventType && typeof eventType === 'string' ? eventType : 'default';
    const attempts = typeof maxAttempts === 'number' && maxAttempts > 0 ? maxAttempts : 5;

    const event = store.createEvent(
      customerId,
      subscription.id,
      type,
      payload,
      attempts
    );

    // Trigger immediate poll so delivery starts without delay
    setImmediate(() => dispatcher.pollAndDispatch());

    res.status(202).json({
      message: 'Event accepted for delivery',
      event,
    });
  });

  /**
   * List events with optional filters (customerId, status, pagination)
   * GET /events?customerId=...&status=...&limit=...&offset=...
   */
  router.get('/events', (req: Request, res: Response) => {
    const customerId = typeof req.query.customerId === 'string' ? req.query.customerId : undefined;
    const status = typeof req.query.status === 'string' ? (req.query.status as EventStatus) : undefined;
    const limit = req.query.limit ? parseInt(req.query.limit as string, 10) : 50;
    const offset = req.query.offset ? parseInt(req.query.offset as string, 10) : 0;

    const result = store.listEvents({
      customerId,
      status,
      limit,
      offset,
    });

    res.json(result);
  });

  /**
   * Get event delivery status and full attempt history
   * GET /events/:id
   */
  router.get('/events/:id', (req: Request, res: Response) => {
    const event = store.getEventById(req.params.id);
    if (!event) {
      res.status(404).json({ error: 'Event not found' });
      return;
    }
    res.json({ event });
  });

  /**
   * Manually replay / retry a failed event (Dead-Letter queue recovery)
   * POST /events/:id/retry
   */
  router.post('/events/:id/retry', (req: Request, res: Response) => {
    const event = store.getEventById(req.params.id);
    if (!event) {
      res.status(404).json({ error: 'Event not found' });
      return;
    }

    const updated = store.retryEvent(req.params.id);
    setImmediate(() => dispatcher.pollAndDispatch());

    res.json({
      message: 'Event requeued for delivery',
      event: updated,
    });
  });

  /**
   * Health and metrics endpoint
   * GET /health
   */
  router.get('/health', (_req: Request, res: Response) => {
    const stats = store.getStats();
    const metrics = dispatcher.getMetrics();

    res.json({
      status: 'ok',
      uptimeSeconds: process.uptime(),
      stats,
      dispatcher: metrics,
    });
  });

  return router;
}

import express from 'express';
import { WebhookStore } from './db.js';
import { WebhookDispatcher } from './dispatcher.js';
import { createApiRouter } from './api.js';

export function createApp(dbPath?: string, dispatcherOptions?: any) {
  const app = express();
  app.use(express.json());

  const store = new WebhookStore(dbPath ?? 'webhooks.db');
  const dispatcher = new WebhookDispatcher({
    store,
    ...dispatcherOptions,
  });

  app.use('/api', createApiRouter(store, dispatcher));

  // Root welcome / info endpoint
  app.get('/', (_req, res) => {
    res.json({
      service: 'Reliable Webhook Delivery Service',
      version: '1.0.0',
      endpoints: {
        health: 'GET /api/health',
        registerSubscription: 'POST /api/subscriptions',
        listSubscriptions: 'GET /api/subscriptions',
        ingestEvent: 'POST /api/events',
        listEvents: 'GET /api/events',
        getEventStatus: 'GET /api/events/:id',
        manualRetry: 'POST /api/events/:id/retry',
      },
    });
  });

  return { app, store, dispatcher };
}

// Start standalone server when run directly
if (process.env.NODE_ENV !== 'test') {
  const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
  const DB_PATH = process.env.DB_PATH || 'webhooks.db';

  const { app, store, dispatcher } = createApp(DB_PATH);

  dispatcher.start();

  const server = app.listen(PORT, () => {
    console.log(`
=============================================================
🚀 Webhook Delivery Service is running on http://localhost:${PORT}
💾 SQLite Database: ${DB_PATH}
⚡ Dispatcher started: Exponential backoff with fair queueing
=============================================================
Endpoints:
  POST /api/subscriptions  - Register customer endpoint
  POST /api/events         - Publish event to customer
  GET  /api/events/:id     - Inspect event & delivery attempt history
  GET  /api/health         - View queue stats & worker metrics
=============================================================
`);
  });

  // Graceful shutdown handling
  const shutdown = () => {
    console.log('\nShutting down gracefully...');
    dispatcher.stop();
    server.close(() => {
      store.close();
      console.log('Server and database closed. Bye!');
      process.exit(0);
    });
  };

  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}

import express, { Request, Response } from 'express';

const app = express();
app.use(express.json());

interface ReceivedWebhook {
  id: string;
  path: string;
  timestamp: string;
  headers: Record<string, any>;
  body: any;
}

const receivedWebhooks: ReceivedWebhook[] = [];
let flakyAttemptCount = 0;

// Log every incoming request
app.use((req, _res, next) => {
  console.log(`[MockCustomer] Received ${req.method} ${req.path}`);
  next();
});

// 1. Success endpoint: Always returns 200 OK
app.post('/webhook/success', (req: Request, res: Response) => {
  const item: ReceivedWebhook = {
    id: req.headers['x-webhook-id'] as string || 'unknown',
    path: req.path,
    timestamp: new Date().toISOString(),
    headers: req.headers,
    body: req.body,
  };
  receivedWebhooks.push(item);

  console.log(`[MockCustomer] ✅ /webhook/success received event ID: ${item.id}`);
  res.status(200).json({ received: true, eventId: item.id });
});

// 2. Flaky endpoint: Fails first 2 times with 503, succeeds on 3rd attempt
app.post('/webhook/flaky', (req: Request, res: Response) => {
  flakyAttemptCount++;
  const eventId = req.headers['x-webhook-id'] as string;
  const attempt = req.headers['x-webhook-attempt'] as string;

  console.log(`[MockCustomer] 🔄 /webhook/flaky attempt #${flakyAttemptCount} (Header attempt: ${attempt})`);

  if (flakyAttemptCount < 3) {
    res.status(503).json({
      error: 'Service Temporarily Unavailable (Simulated failure)',
      flakyAttemptCount,
    });
  } else {
    receivedWebhooks.push({
      id: eventId,
      path: req.path,
      timestamp: new Date().toISOString(),
      headers: req.headers,
      body: req.body,
    });
    console.log(`[MockCustomer] ✅ /webhook/flaky recovered! Event ID: ${eventId}`);
    res.status(200).json({
      received: true,
      recoveredAtAttempt: flakyAttemptCount,
      eventId,
    });
  }
});

// 3. Always failing endpoint: Always returns 500
app.post('/webhook/failing', (req: Request, res: Response) => {
  const eventId = req.headers['x-webhook-id'] as string;
  const attempt = req.headers['x-webhook-attempt'] as string;

  console.log(`[MockCustomer] ❌ /webhook/failing rejected event ${eventId} (attempt ${attempt})`);
  res.status(500).json({ error: 'Endpoint Internal Server Error (Always fails)' });
});

// 4. Slow endpoint: Takes 6000ms to respond (triggers client timeout)
app.post('/webhook/slow', async (req: Request, res: Response) => {
  console.log('[MockCustomer] ⏳ /webhook/slow hanging for 6s...');
  await new Promise((r) => setTimeout(r, 6000));
  res.status(200).json({ received: true, delayed: true });
});

// Inspection & Reset endpoints
app.get('/webhook/received', (_req: Request, res: Response) => {
  res.json({ count: receivedWebhooks.length, received: receivedWebhooks });
});

app.post('/webhook/reset', (_req: Request, res: Response) => {
  flakyAttemptCount = 0;
  receivedWebhooks.length = 0;
  console.log('[MockCustomer] State reset.');
  res.json({ message: 'State reset successfully' });
});

const PORT = process.env.MOCK_PORT ? parseInt(process.env.MOCK_PORT, 10) : 4000;
app.listen(PORT, () => {
  console.log(`
=============================================================
🤖 Mock Customer Receiver is running on http://localhost:${PORT}
=============================================================
Available mock endpoints:
  POST /webhook/success  - Always returns 200 OK
  POST /webhook/flaky    - Fails 2x with 503, then returns 200 on 3rd attempt
  POST /webhook/failing  - Always returns 500 Internal Error
  POST /webhook/slow     - Hangs for 6s (tests timeout)
  GET  /webhook/received - Inspect received webhooks
  POST /webhook/reset    - Reset flaky counter and logs
=============================================================
`);
});

import { test, describe, before, after } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import express from 'express';
import { createApp } from '../server.js';
import { verifySignature } from '../crypto.js';

describe('Webhook Delivery Service Integration Tests', () => {
  let mockServer: http.Server;
  let mockPort: number;
  let serviceApp: express.Express;
  let store: any;
  let dispatcher: any;

  // Track mock requests
  let receivedRequests: Array<{
    headers: http.IncomingHttpHeaders;
    body: any;
  }> = [];

  let flakyAttempts = 0;

  before(async () => {
    // 1. Start mock server
    const mockApp = express();
    mockApp.use(express.json());

    mockApp.post('/target/success', (req, res) => {
      receivedRequests.push({ headers: req.headers, body: req.body });
      res.status(200).json({ ok: true });
    });

    mockApp.post('/target/flaky', (req, res) => {
      flakyAttempts++;
      if (flakyAttempts < 3) {
        res.status(503).json({ error: 'Service Unavailable' });
      } else {
        receivedRequests.push({ headers: req.headers, body: req.body });
        res.status(200).json({ ok: true });
      }
    });

    mockApp.post('/target/fail', (req, res) => {
      res.status(500).json({ error: 'Fatal error' });
    });

    mockServer = http.createServer(mockApp);
    await new Promise<void>((resolve) => {
      mockServer.listen(0, () => {
        mockPort = (mockServer.address() as any).port;
        resolve();
      });
    });

    // 2. Start Webhook Service with in-memory DB and short retry delays for testing
    const created = createApp(':memory:', {
      pollIntervalMs: 50,
      policy: {
        maxAttempts: 3,
        initialDelayMs: 100, // fast retries for tests
        backoffFactor: 2,
        maxDelayMs: 1000,
        jitterFactor: 0.05,
        requestTimeoutMs: 1000,
      },
    });

    serviceApp = created.app;
    store = created.store;
    dispatcher = created.dispatcher;
    dispatcher.start();
  });

  after(() => {
    dispatcher.stop();
    store.close();
    mockServer.close();
  });

  test('1. Register customer subscription and verify HMAC secret', () => {
    const sub = store.upsertSubscription(
      'cust_alpha',
      `http://127.0.0.1:${mockPort}/target/success`,
      'secret_key_123'
    );

    assert.equal(sub.customer_id, 'cust_alpha');
    assert.equal(sub.endpoint_url, `http://127.0.0.1:${mockPort}/target/success`);
    assert.equal(sub.secret, 'secret_key_123');
    assert.equal(sub.status, 'active');
  });

  test('2. Successfully ingest and deliver event (Happy Path with Signature verification)', async () => {
    receivedRequests = [];

    const event = store.createEvent(
      'cust_alpha',
      store.getSubscriptionByCustomerId('cust_alpha').id,
      'order.created',
      { orderId: 101, amount: 250000 }
    );

    assert.equal(event.status, 'pending');
    assert.equal(event.sequence_number, 1);

    // Wait for dispatcher to pick up and deliver
    await new Promise((r) => setTimeout(r, 300));

    const updated = store.getEventById(event.id);
    assert.equal(updated.status, 'delivered');
    assert.equal(updated.attempt_count, 1);
    assert.ok(updated.delivered_at);
    assert.equal(updated.attempts.length, 1);
    assert.equal(updated.attempts[0].status_code, 200);

    // Verify received headers at mock server
    assert.equal(receivedRequests.length, 1);
    const req = receivedRequests[0];
    assert.equal(req.headers['x-webhook-id'], event.id);
    assert.equal(req.headers['x-webhook-sequence'], '1');
    assert.equal(req.body.orderId, 101);

    // Verify HMAC SHA-256 signature
    const signature = req.headers['x-webhook-signature'] as string;
    assert.ok(signature.startsWith('sha256='));
    const isValid = verifySignature(
      JSON.stringify(req.body),
      'secret_key_123',
      signature
    );
    assert.equal(isValid, true, 'HMAC signature should be valid');
  });

  test('3. Retry flaky endpoint with exponential backoff until success', async () => {
    flakyAttempts = 0;
    receivedRequests = [];

    store.upsertSubscription(
      'cust_flaky',
      `http://127.0.0.1:${mockPort}/target/flaky`,
      'secret_flaky'
    );

    const sub = store.getSubscriptionByCustomerId('cust_flaky');
    const event = store.createEvent('cust_flaky', sub.id, 'payment.pending', {
      invoiceId: 'inv_999',
    });

    // First attempt will fail immediately (flakyAttempts = 1, 503)
    await new Promise((r) => setTimeout(r, 80));
    let current = store.getEventById(event.id);
    assert.equal(current.status, 'pending');
    assert.equal(current.attempt_count, 1);
    assert.equal(current.attempts[0].status_code, 503);

    // Wait for retry 2 (flakyAttempts = 2, 503) and retry 3 (recovers with 200 OK)
    await new Promise((r) => setTimeout(r, 600));

    current = store.getEventById(event.id);
    assert.equal(current.status, 'delivered');
    assert.equal(current.attempt_count, 3);
    assert.equal(current.attempts.length, 3);
    assert.equal(current.attempts[2].status_code, 200);
  });

  test('4. Terminal failed state when endpoint never responds with 2xx', async () => {
    store.upsertSubscription(
      'cust_dead',
      `http://127.0.0.1:${mockPort}/target/fail`,
      'secret_dead'
    );

    const sub = store.getSubscriptionByCustomerId('cust_dead');
    const event = store.createEvent(
      'cust_dead',
      sub.id,
      'user.deleted',
      { userId: 444 },
      3 // max 3 attempts
    );

    // Wait for all 3 attempts to exhaust
    await new Promise((r) => setTimeout(r, 1200));

    const finalEvent = store.getEventById(event.id);
    assert.equal(finalEvent.status, 'failed');
    assert.equal(finalEvent.attempt_count, 3);
    assert.equal(finalEvent.attempts.length, 3);
    assert.ok(finalEvent.last_error.includes('Max attempts (3) exceeded'));
  });

  test('5. Dead-Letter replay: Manual retry of a failed event', async () => {
    // We update subscription to a working endpoint before retrying
    store.upsertSubscription(
      'cust_dead',
      `http://127.0.0.1:${mockPort}/target/success`,
      'secret_dead'
    );

    const events = store.listEvents({ customerId: 'cust_dead', status: 'failed' });
    assert.ok(events.events.length > 0);
    const failedEvent = events.events[0];

    // Replay event
    const requeued = store.retryEvent(failedEvent.id);
    assert.equal(requeued.status, 'pending');
    assert.equal(requeued.attempt_count, 0);

    // Wait for delivery
    await new Promise((r) => setTimeout(r, 300));

    const delivered = store.getEventById(failedEvent.id);
    assert.equal(delivered.status, 'delivered');
  });

  test('6. Monotonic Sequence Numbering per customer', () => {
    const sub = store.getSubscriptionByCustomerId('cust_alpha');
    const e1 = store.createEvent('cust_alpha', sub.id, 'item.1', { n: 1 });
    const e2 = store.createEvent('cust_alpha', sub.id, 'item.2', { n: 2 });
    const e3 = store.createEvent('cust_alpha', sub.id, 'item.3', { n: 3 });

    assert.equal(e1.sequence_number, 2); // 1 was used in test 2
    assert.equal(e2.sequence_number, 3);
    assert.equal(e3.sequence_number, 4);
  });
});

