import { test, describe, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from '../server.js';
import { verifySignature } from '../crypto.js';

describe('Webhook Delivery Service Integration Tests', () => {
  let store: any;
  let dispatcher: any;

  // Track mock requests
  let receivedRequests: Array<{
    url: string;
    headers: Record<string, string>;
    body: any;
  }> = [];

  let flakyAttempts = 0;

  // Hermetic mock fetch implementation for tests
  const mockFetch: typeof fetch = async (input, init) => {
    const url = input.toString();
    const headers = (init?.headers as Record<string, string>) || {};
    const body = init?.body ? JSON.parse(init.body as string) : null;

    if (url.includes('/target/success')) {
      receivedRequests.push({ url, headers, body });
      return new Response(JSON.stringify({ ok: true }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    if (url.includes('/target/flaky')) {
      flakyAttempts++;
      if (flakyAttempts < 3) {
        return new Response(JSON.stringify({ error: 'Service Unavailable' }), {
          status: 503,
          headers: { 'Content-Type': 'application/json' },
        });
      } else {
        receivedRequests.push({ url, headers, body });
        return new Response(JSON.stringify({ ok: true, recovered: true }), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        });
      }
    }

    if (url.includes('/target/fail')) {
      return new Response(JSON.stringify({ error: 'Fatal error' }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      });
    }

    return new Response('Not Found', { status: 404 });
  };

  before(() => {
    process.env.NODE_ENV = 'test';

    const created = createApp(':memory:', {
      pollIntervalMs: 50,
      fetchFn: mockFetch,
      policy: {
        maxAttempts: 3,
        initialDelayMs: 100, // fast retries for tests
        backoffFactor: 2,
        maxDelayMs: 1000,
        jitterFactor: 0.05,
        requestTimeoutMs: 1000,
      },
    });

    store = created.store;
    dispatcher = created.dispatcher;
    dispatcher.start();
  });

  after(() => {
    dispatcher.stop();
    store.close();
  });

  test('1. Register customer subscription and verify HMAC secret', () => {
    const sub = store.upsertSubscription(
      'cust_alpha',
      'https://api.customer-a.com/target/success',
      'secret_key_123'
    );

    assert.equal(sub.customer_id, 'cust_alpha');
    assert.equal(sub.endpoint_url, 'https://api.customer-a.com/target/success');
    assert.equal(sub.secret, 'secret_key_123');
    assert.equal(sub.status, 'active');
  });

  test('2. Successfully ingest and deliver event (Happy Path with Signature verification)', async () => {
    receivedRequests = [];

    const event = store.createEvent(
      'cust_alpha',
      store.getSubscriptionByCustomerId('cust_alpha').id,
      'order.created',
      { orderId: 101, amount: 250000 }
    );

    assert.equal(event.status, 'pending');
    assert.equal(event.sequence_number, 1);

    // Wait for dispatcher poll
    await new Promise((r) => setTimeout(r, 200));

    const updated = store.getEventById(event.id);
    assert.equal(updated.status, 'delivered');
    assert.equal(updated.attempt_count, 1);
    assert.ok(updated.delivered_at);
    assert.equal(updated.attempts.length, 1);
    assert.equal(updated.attempts[0].status_code, 200);

    // Verify received headers at mock endpoint
    assert.equal(receivedRequests.length, 1);
    const req = receivedRequests[0];
    assert.equal(req.headers['X-Webhook-ID'], event.id);
    assert.equal(req.headers['X-Webhook-Sequence'], '1');
    assert.equal(req.body.orderId, 101);

    // Verify HMAC SHA-256 signature
    const signature = req.headers['X-Webhook-Signature'];
    assert.ok(signature.startsWith('sha256='));
    const isValid = verifySignature(
      JSON.stringify(req.body),
      'secret_key_123',
      signature
    );
    assert.equal(isValid, true, 'HMAC signature should be valid');
  });

  test('3. Retry flaky endpoint with exponential backoff until success', async () => {
    flakyAttempts = 0;
    receivedRequests = [];

    store.upsertSubscription(
      'cust_flaky',
      'https://api.flaky-service.com/target/flaky',
      'secret_flaky'
    );

    const sub = store.getSubscriptionByCustomerId('cust_flaky');
    const event = store.createEvent('cust_flaky', sub.id, 'payment.pending', {
      invoiceId: 'inv_999',
    });

    // Wait for first attempt (flakyAttempts = 1, 503)
    await new Promise((r) => setTimeout(r, 80));
    let current = store.getEventById(event.id);
    assert.equal(current.status, 'pending');
    assert.equal(current.attempt_count, 1);
    assert.equal(current.attempts[0].status_code, 503);

    // Wait for retries (attempt 2 fails 503, attempt 3 succeeds 200)
    await new Promise((r) => setTimeout(r, 600));

    current = store.getEventById(event.id);
    assert.equal(current.status, 'delivered');
    assert.equal(current.attempt_count, 3);
    assert.equal(current.attempts.length, 3);
    assert.equal(current.attempts[2].status_code, 200);
  });

  test('4. Terminal failed state when endpoint never responds with 2xx', async () => {
    store.upsertSubscription(
      'cust_dead',
      'https://api.down-service.com/target/fail',
      'secret_dead'
    );

    const sub = store.getSubscriptionByCustomerId('cust_dead');
    const event = store.createEvent(
      'cust_dead',
      sub.id,
      'user.deleted',
      { userId: 444 },
      3 // max 3 attempts
    );

    // Wait for all 3 attempts to exhaust
    await new Promise((r) => setTimeout(r, 1200));

    const finalEvent = store.getEventById(event.id);
    assert.equal(finalEvent.status, 'failed');
    assert.equal(finalEvent.attempt_count, 3);
    assert.equal(finalEvent.attempts.length, 3);
    assert.ok(finalEvent.last_error.includes('Max attempts (3) exceeded'));
  });

  test('5. Dead-Letter replay: Manual retry of a failed event', async () => {
    // We update subscription to a working endpoint before retrying
    store.upsertSubscription(
      'cust_dead',
      'https://api.customer-a.com/target/success',
      'secret_dead'
    );

    const events = store.listEvents({ customerId: 'cust_dead', status: 'failed' });
    assert.ok(events.events.length > 0);
    const failedEvent = events.events[0];

    // Replay event
    const requeued = store.retryEvent(failedEvent.id);
    assert.equal(requeued.status, 'pending');
    assert.equal(requeued.attempt_count, 0);

    // Wait for delivery
    await new Promise((r) => setTimeout(r, 200));

    const delivered = store.getEventById(failedEvent.id);
    assert.equal(delivered.status, 'delivered');
  });

  test('6. Monotonic Sequence Numbering per customer', () => {
    const sub = store.getSubscriptionByCustomerId('cust_alpha');
    const e1 = store.createEvent('cust_alpha', sub.id, 'item.1', { n: 1 });
    const e2 = store.createEvent('cust_alpha', sub.id, 'item.2', { n: 2 });
    const e3 = store.createEvent('cust_alpha', sub.id, 'item.3', { n: 3 });

    assert.equal(e1.sequence_number, 2); // 1 was used in test 2
    assert.equal(e2.sequence_number, 3);
    assert.equal(e3.sequence_number, 4);
  });
});

import { createApp } from './server.js';
import { verifySignature } from './crypto.js';

async function sleep(ms: number) {
  return new Promise((r) => setTimeout(r, ms));
}

async function runDemo() {
  console.log(`
=============================================================
🌟 WEBHOOK DELIVERY SERVICE - LIVE DEMONSTRATION 🌟
=============================================================
`);

  const mockEndpoints: Record<string, { attempts: number; responses: number[] }> = {
    'https://customer-a.example/webhook': { attempts: 0, responses: [200] },
    'https://customer-b.example/webhook': { attempts: 0, responses: [503, 503, 200] },
    'https://customer-c.example/webhook': { attempts: 0, responses: [500, 500, 500, 500, 500] },
  };

  const demoFetch: typeof fetch = async (input, init) => {
    const url = input.toString();
    const config = mockEndpoints[url];
    const attempt = init?.headers ? (init.headers as any)['X-Webhook-Attempt'] : 1;
    const eventId = init?.headers ? (init.headers as any)['X-Webhook-ID'] : '';

    if (!config) {
      return new Response('Not Found', { status: 404 });
    }

    config.attempts++;
    const statusIndex = Math.min(config.attempts - 1, config.responses.length - 1);
    const status = config.responses[statusIndex];

    console.log(
      `  [HTTP POST] -> ${url} | Event: ${eventId} | Attempt #${attempt} => HTTP ${status}`
    );

    if (status >= 200 && status < 300) {
      return new Response(JSON.stringify({ received: true }), {
        status,
        headers: { 'Content-Type': 'application/json' },
      });
    } else {
      return new Response(JSON.stringify({ error: `Mock Failure (HTTP ${status})` }), {
        status,
        headers: { 'Content-Type': 'application/json' },
      });
    }
  };

  process.env.NODE_ENV = 'test'; // prevent default server listen

  // Fast retry delays for demo
  const { store, dispatcher } = createApp(':memory:', {
    pollIntervalMs: 50,
    fetchFn: demoFetch,
    policy: {
      maxAttempts: 3,
      initialDelayMs: 300,
      backoffFactor: 2,
      maxDelayMs: 2000,
      jitterFactor: 0.1,
      requestTimeoutMs: 1000,
    },
  });

  dispatcher.start();

  console.log('📌 STEP 1: Registering Customer Subscriptions');
  const subA = store.upsertSubscription('cust_healthy', 'https://customer-a.example/webhook', 'secret_a');
  const subB = store.upsertSubscription('cust_flaky', 'https://customer-b.example/webhook', 'secret_b');
  const subC = store.upsertSubscription('cust_down', 'https://customer-c.example/webhook', 'secret_c');

  console.log(`  ✓ Registered Customer A: ${subA.endpoint_url} (Secret: ${subA.secret})`);
  console.log(`  ✓ Registered Customer B: ${subB.endpoint_url} (Secret: ${subB.secret})`);
  console.log(`  ✓ Registered Customer C: ${subC.endpoint_url} (Secret: ${subC.secret})`);

  console.log('\n📌 STEP 2: Ingesting Events for All 3 Customers');
  const evA = store.createEvent('cust_healthy', subA.id, 'order.completed', {
    orderId: 'ORD-101',
    amount: 150000,
    currency: 'IDR',
  });
  console.log(`  ✓ Queued Event A (${evA.id}) - Target: Healthy endpoint`);

  const evB = store.createEvent('cust_flaky', subB.id, 'payment.confirmed', {
    paymentId: 'PAY-202',
    status: 'PAID',
  });
  console.log(`  ✓ Queued Event B (${evB.id}) - Target: Flaky endpoint (fails 2x, then recovers)`);

  const evC = store.createEvent('cust_down', subC.id, 'user.signup', {
    userId: 'USR-303',
    email: 'alex@example.com',
  }, 3); // max 3 attempts
  console.log(`  ✓ Queued Event C (${evC.id}) - Target: Down endpoint (permanent failure)`);

  console.log('\n📌 STEP 3: Dispatcher Processing Events with Retries & Backoff...');
  await sleep(2500);

  console.log('\n📌 STEP 4: Checking Event Delivery Statuses & Attempt History');

  const checkEvent = (id: string) => {
    const ev = store.getEventById(id);
    console.log(`\n--- Event [${ev.id}] (${ev.event_type}) ---`);
    console.log(`  Status:         ${ev.status.toUpperCase()}`);
    console.log(`  Sequence No:    #${ev.sequence_number}`);
    console.log(`  Attempt Count:  ${ev.attempt_count} / ${ev.max_attempts}`);
    console.log(`  Delivered At:   ${ev.delivered_at ? new Date(ev.delivered_at).toISOString() : 'N/A'}`);
    console.log(`  Last Error:     ${ev.last_error || 'None'}`);
    console.log(`  Attempt Logs:`);
    for (const att of ev.attempts) {
      console.log(
        `    - Attempt #${att.attempt_number}: HTTP ${att.status_code || 'ERR'} | Duration: ${att.duration_ms}ms | Error: ${att.error_message || 'None'}`
      );
    }
  };

  checkEvent(evA.id);
  checkEvent(evB.id);
  checkEvent(evC.id);

  console.log('\n📌 STEP 5: Dead-Letter Queue Recovery (Manual Replay)');
  console.log(`  Customer C fixed their server! Updating endpoint response to 200 OK...`);
  mockEndpoints['https://customer-c.example/webhook'].responses = [200];
  mockEndpoints['https://customer-c.example/webhook'].attempts = 0;

  console.log(`  Calling POST /api/events/${evC.id}/retry...`);
  store.retryEvent(evC.id);

  await sleep(500);

  const evCRecovered = store.getEventById(evC.id);
  console.log(`  ✓ Event C Status after Replay: ${evCRecovered.status.toUpperCase()}`);
  console.log(`  ✓ Event C Delivered At:        ${new Date(evCRecovered.delivered_at).toISOString()}`);

  console.log('\n📌 STEP 6: Final System Stats');
  console.log(store.getStats());

  dispatcher.stop();
  store.close();

  console.log(`
=============================================================
🎉 DEMONSTRATION COMPLETE: ALL SCENARIOS VERIFIED!
=============================================================
`);
}

runDemo().catch(console.error);

import express from 'express';
import { WebhookStore } from './db.js';
import { WebhookDispatcher, DispatcherOptions } from './dispatcher.js';
import { createApiRouter } from './api.js';

export interface AppOptions {
  dbPath?: string;
  dispatcherOptions?: Partial<DispatcherOptions>;
}

export function createApp(options?: AppOptions) {
  const app = express();
  app.use(express.json());

  const store = new WebhookStore(options?.dbPath ?? 'webhooks.db');
  const dispatcher = new WebhookDispatcher({
    store,
    ...options?.dispatcherOptions,
  });

  app.use('/api', createApiRouter(store, dispatcher));

  // Root endpoint
  app.get('/', (_req, res) => {
    res.json({
      service: 'Reliable Webhook Delivery Service',
      version: '1.0.0',
      endpoints: {
        health: 'GET /api/health',
        registerSubscription: 'POST /api/subscriptions',
        listSubscriptions: 'GET /api/subscriptions',
        ingestEvent: 'POST /api/events',
        listEvents: 'GET /api/events',
        getEventStatus: 'GET /api/events/:id',
        manualRetry: 'POST /api/events/:id/retry',
      },
    });
  });

  return { app, store, dispatcher };
}

import { createApp } from './app.js';

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
const DB_PATH = process.env.DB_PATH || 'webhooks.db';

const { app, store, dispatcher } = createApp({ dbPath: DB_PATH });

dispatcher.start();

const server = app.listen(PORT, () => {
  console.log(`
=============================================================
🚀 Webhook Delivery Service is running on http://localhost:${PORT}
💾 SQLite Database: ${DB_PATH}
⚡ Dispatcher started: Exponential backoff with fair queueing
=============================================================
Endpoints:
  POST /api/subscriptions  - Register customer endpoint
  POST /api/events         - Publish event to customer
  GET  /api/events/:id     - Inspect event & delivery attempt history
  GET  /api/health         - View queue stats & worker metrics
=============================================================
`);
});

// Graceful shutdown handling
const shutdown = () => {
  console.log('\nShutting down gracefully...');
  dispatcher.stop();
  server.close(() => {
    store.close();
    console.log('Server and database closed. Bye!');
    process.exit(0);
  });
};

process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

